CREATE COLUMN TABLE "TEST_AP"."OCMN" ("GUID" NVARCHAR(32) NOT NULL , "Name" NVARCHAR(100), "Father" NVARCHAR(32), "Type" NVARCHAR(1) DEFAULT 'C', "SubMenu" NVARCHAR(1) DEFAULT 'N', "MenuUID" NVARCHAR(50), "ObjectType" INTEGER CS_INT, "ObjectKey" NVARCHAR(200), "PermFolder" INTEGER CS_INT, "SortOrder" INTEGER CS_INT, PRIMARY KEY ("GUID")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "OCMN_UID_KEY" ON "TEST_AP"."OCMN" ( "MenuUID" ASC )